// Regenerates scripts/install-edge-functions.sh from supabase/functions, so the paste-in
// installer for the edge-functions container terminal can never drift from the repo.
//   npm run build:installer
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')), '..');
const FILES = JSON.parse(fs.readFileSync(path.join(root, 'supabase/functions/deploy-manifest.json'), 'utf8')).files;

let out = `#!/bin/sh
# Installs the Flutterwave and Business Leak Test edge functions.
# GENERATED by scripts/build-installer.mjs from supabase/functions. Do not edit by hand.
# Run INSIDE the supabase edge-functions container terminal (Coolify -> supabase -> edge functions -> Terminal).
# Writes into /home/deno/functions. Safe to run twice. Works in plain sh; needs no curl.
set -eu
D="\${FUNCTIONS_DIR:-/home/deno/functions}"
`;
for (const dir of [...new Set(FILES.map((f) => path.dirname(f)))]) out += `mkdir -p "$D/${dir}"\n`;

FILES.forEach((file, i) => {
  const tag = `EOF_${i}_${path.basename(path.dirname(file)).replace(/\W/g, '').toUpperCase()}`;
  const body = fs.readFileSync(path.join(root, 'supabase/functions', file), 'utf8').replace(/\r\n/g, '\n').replace(/\n+$/, '');
  if (body.split('\n').includes(tag)) throw new Error(`${file} contains its own heredoc tag`);
  out += `\ncat > "$D/${file}" <<'${tag}'\n${body}\n${tag}\necho "wrote ${file}"\n`;
});
out += `\necho\necho "Done. $(ls "$D" | tr '\n' ' ')"\necho "Now restart the supabase-edge-functions container so the changes load."\n`;

fs.writeFileSync(path.join(root, 'scripts/install-edge-functions.sh'), out);
console.log(`wrote install-edge-functions.sh (${FILES.length} files, ${out.split('\n').length} lines)`);
